class Solution:
    def checkValidString(self, s: str) -> bool:
        open_stack = []
        star_stack = []
        for i, char in enumerate(s):

            # Add open brackets to open_stack and star to star_stack
            if char == "(":
                open_stack.append(i)
            elif char == "*":
                star_stack.append(i)

            # Check the current opening brackets or star, pop them in case they match the closing bracket
            # If no matching bracket is found, then the expression is not valid.
            elif char == ")":
                if open_stack:
                    open_stack.pop()
                elif star_stack:
                    star_stack.pop()
                else:
                    return False

        # Check the length of the remaining stacks
        while open_stack and star_stack:
            o = open_stack.pop()
            s = star_stack.pop()

            if o > s:
                return False

        return len(open_stack) == 0

public class MyDataStructure {
    private int length;
    private int array[];

    public MyDataStructure(int size) {
        this.length = size;
        array = new int[size];
    }

    public void add(int value) {
        if (length == array.length) {
            increaseSize();
        }
        array[length++] = value;
    }

    private void increaseSize() {
        int newLength = array.length * 2;
        int[] newArray = new int[newLength];
        for (int i = 0; i < length; i++) {
            newArray[i] = array[i];
        }
        array = newArray;
    }

    public void get(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException();
        }
        return array[index];
    }

    public void remove(int value) {
        for (int i = 0; i < length; i++) {
            if (array[i] == value) {
                for (int j = i; j < length-1; j++) {
                    array[j] = array[j+1];
                }
                length--;
                return;
            }
        }
    }
}

